async function api(path:string,method='GET',input?:unknown,signal?:AbortSignal){
  const response=await fetch(`/api/studio/${path}${path.includes('?')?'&':'?'}profileId=${profileId}`,{method,signal,headers:{'Content-Type':'application/json'},...(input===undefined?{}:{body:JSON.stringify(input)})});
  const body=await response.text();let result;try{result=JSON.parse(body);}catch{throw Object.assign(new Error(`The service returned an error page (HTTP ${response.status}). Your saved show is kept; try Resume again shortly.`),{status:response.status,code:'GATEWAY_RESPONSE'});}if(!response.ok)throw Object.assign(new Error(typeof result.error==='string'?result.error:'The studio could not complete that action.'),{status:response.status,code:result.code});return result;
}
