async function upload(path:string,blob:Blob){const response=await fetch(`/api/studio/${path}${path.includes('?')?'&':'?'}profileId=${profileId}`,{method:'POST',headers:{'Content-Type':'application/octet-stream'},body:blob});const result=await response.json();if(!response.ok)throw new Error(result.error||'Upload did not finish. Saved take is kept.');return result;}
async function saveScreenMedia(file:File,sourceUrl?:string){
 if(!channel)throw new Error('Choose a room first.');const previous=channel.screen??null;
 try{await screen.file(file);const {asset}=await upload(`media?mime=${encodeURIComponent(file.type)}&name=${encodeURIComponent(file.name)}`,file);await mutate('channels/'+channel.id,{...tokens(channel),operation:'screen',screen:{assetId:asset.id,muted:true,loop:true,startMs:0,...(sourceUrl?{sourceUrl}:{})}},'PATCH');screenAssetId=asset.id;screen.local=false;}catch(error){await restoreScreen(previous);throw error;}
}
async function restoreScreen(setting=channel?.screen){if(!setting){screen.clear();screenAssetId='';return;}const {asset}=await api(`media/${setting.assetId}/info`);await screen.url(`${location.origin}/api/studio/media/${asset.id}?profileId=${profileId}`,asset.mime==='image/gif'?'gif':'video');screen.settings(setting.muted,setting.loop,setting.startMs);screenAssetId=asset.id;screen.pause();}
function clipForTake(take:Take){const saved=channel&&Object.hasOwn(channel,'screen')?channel.screen:take.edition?.screen;return saved?{...saved,muted:screenAssetId===saved.assetId?screen.muted:saved.muted}:null;}
async function playShowClip(restart=false){screen.endExport();if(screen.kind==='none')return;if(restart)screen.restart();if(!screen.playing)await screen.toggle();screen.connectAudio(timeline.context,timeline.mix);}
async function watchTake(take:Take){if(player.active)await player.pause();const selectedScreen=clipForTake(take),preview={...take,edition:{...(take.edition||defaultEdition(take)),screen:selectedScreen}};await timeline.load(preview,async id=>(await api('audio/'+id)).asset);outputTake=preview;mode='performance';await restoreScreen(selectedScreen);await playShowClip(true);scene?.coverage('auto');watched=true;await timeline.play(0);}
async function finishRecording(){if(recorder.offline){recorder.cancel();recordingJob=null;return;}if(!recordingJob||!recorder.active)return;const job=recordingJob,complete=timeline.timeMs>=timeline.durationMs-150;recordingJob=null;stopTimeline();const blob=await recorder.stop();if(!complete){mode='takes';tell('Recording stopped early. Your saved take is kept; record it again when ready.');return;}await run(async()=>{status='Saving and preparing your video…';render();await upload(`exports/${job.id}/recording`,blob);mode='exports';await refreshExports();status='Video uploaded. Processing continues on the server.';});}
function downloadStarted(id:string,owner=profileId){try{return JSON.parse(localStorage.getItem('goc-export-downloads-v1:'+owner)||'[]').includes(id);}catch{return false;}}
function rememberDownload(id:string,owner:string){try{const key='goc-export-downloads-v1:'+owner,saved=JSON.parse(localStorage.getItem(key)||'[]');localStorage.setItem(key,JSON.stringify([...new Set([...(Array.isArray(saved)?saved.filter(isId):[]),id])]));}catch{}}
function downloadFile(url:string,name:string){const anchor=document.createElement('a');anchor.href=url;anchor.download=name;document.body.append(anchor);anchor.click();anchor.remove();}
async function autoDownloadExport(job:ExportJob){const owner=profileId;if(autoExportPolling.has(job.id)||downloadStarted(job.id,owner))return;autoExportPolling.add(job.id);try{let current=job;while(current.status==='processing'&&!current.recoverable){await new Promise(resolve=>setTimeout(resolve,1200));if(exportPollingStopped||owner!==profileId)return;current=(await api('exports/'+job.id)).job;}if(current.status!=='completed'||exportPollingStopped||owner!==profileId||downloadStarted(job.id,owner))return;rememberDownload(job.id,owner);downloadFile('/api/studio/exports/'+job.id+'/download?profileId='+owner,'show-'+job.format+'.mp4');status='Your video is downloading to your device. Its cloud copy is removed after transfer. If needed, use Download MP4.';render();await new Promise(resolve=>setTimeout(resolve,2000));if(!exportPollingStopped&&owner===profileId){await refreshExports();if(!exportJobs.some(item=>item.id===job.id))status='Your video was sent to your device and removed from cloud storage. The saved take and subtitles remain available.';render();}}catch{if(!exportPollingStopped&&owner===profileId){status='Open Exports to download the video. Your saved take is kept.';render();}}finally{autoExportPolling.delete(job.id);}}
async function refreshExports(){exportJobs=(await api('exports')).exports;for(const job of exportJobs)if(job.status==='completed'||job.status==='processing')void autoDownloadExport(job);}
async function saveTake(){if(!episode?.production)throw new Error('Prepare a show first.');const edition=defaultEdition({productionSnapshot:episode.production} as Take);edition.headline=episode.headline??episode.production.writer?.headline??topicHeadline(episode.plan.premise);if(screenAssetId)edition.screen={...channel?.screen,assetId:screenAssetId,muted:screen.muted,loop:true,startMs:0};const saved=await mutate('episodes/'+episode.id,{...tokens(episode),operation:'accept-take',takeId:uuid(),edition},'PATCH');selectedTakeId=saved.episode.takes.at(-1).id;editDraft=structuredClone(chosenTake()!.edition!);takeView='versions';practice.record('saved-take');status='Take saved. Its original recordings are kept.';}
async function saveEdition(){const take=chosenTake();if(!episode||!take||!editDraft)return;const result=await mutate('episodes/'+episode.id,{...tokens(episode),operation:'accept-take',takeId:uuid(),sourceTakeId:take.id,edition:editDraft},'PATCH');selectedTakeId=result.episode.takes.at(-1).id;editDraft=structuredClone(chosenTake()!.edition!);takeView='versions';practice.record('edit');status='New version saved. Choose the earlier take to undo.';}

const player=new StudioPlayback(()=>episode,api,record=>{accept({episode:record});},(message,failed)=>{if(message)status=message;if(failed)error=true;paused=episode?.production?.status==='paused';render();});
function accept(result:{channel?:ChannelRecord;episode?:EpisodeRecord;library?:StudioLibrary}){
  const record=result.episode;
  if(record&&record.profileId===profileId){
    allEpisodes=allEpisodes.filter(item=>item.id!==record.id);
    if(!record.deletedAt)allEpisodes.push({id:record.id,channelId:record.plan.channelId,premise:record.plan.premise,revision:record.revision,takeCount:record.takes.filter(take=>!take.deletedAt).length,updatedAt:record.updatedAt,storyApproval:approvedStoryTake(record)?record.storyApproval:null});
    allEpisodes.sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt));episodes=allEpisodes.filter(item=>item.channelId===channel?.id);
  }
  if(result.channel&&(!channel||channel.id===result.channel.id)){channel=result.channel;}
  if(result.episode?.deletedAt){if(episode?.id===result.episode.id){player.silence();stopTimeline();timeline.take=null;outputTake=null;episode=null;selectedTakeId='';editDraft=null;}}
  else if(result.episode&&(!channel||channel.id===result.episode.plan.channelId)){episode=result.episode;}
  if(result.library)library=result.library;
}
async function mutate(path:string,input:Record<string,unknown>,method='POST',signal?:AbortSignal){
  if(pending&&pending.input.requestId!==input.requestId)throw new Error('Finish the pending retry, or keep the saved version, before making another change.');
  const command={path:method==='PATCH'?path+'#PATCH':path,input};savePending(command);
  try{const result=await api(path,method,input,signal);accept(result);savePending(null);return result;}catch(problem){if([400,403,404,405,413,415].includes((problem as {status?:number}).status||0))savePending(null);throw problem;}
}
async function recoverStoryReceipt(){
  const work=pending;
  if(!work||!/^episodes\/[a-f0-9-]+#PATCH$/i.test(work.path)||!['approve-story','unapprove-story','delete-take','delete'].includes(String(work.input.operation)))return;
  // Replay only the creator's existing idempotent curation request. Do not
  // automatically restart writing, speech generation or director requests.
  const result=await api(work.path.slice(0,-6),'PATCH',work.input);accept(result);savePending(null);
  if(result.episode?.deletedAt){const target=new URL(location.href);if(target.searchParams.get('episode')===result.episode.id){target.searchParams.delete('episode');history.replaceState(null,'',target);}}
}
async function run(work:()=>Promise<void>){if(busy)return;busy=true;error=false;render();try{await work();}catch(problem){error=true;status=problem instanceof Error?problem.message:'The action could not finish.';}finally{busy=false;render();if(directorCommands.length)void applyDirection().catch(problem=>tell(problem instanceof Error?problem.message:'The direction could not finish. Saved work is kept.'));}}
async function refresh(){const [rooms,people,shows]=await Promise.all([api('channels'),api('characters'),api('episodes')]);channels=rooms.channels;library=people.library;allEpisodes=shows.episodes;if(channel){channel=(await api('channels/'+channel.id)).channel;episodes=allEpisodes.filter(item=>item.channelId===channel!.id);if(episode)episode=(await api('episodes/'+episode.id)).episode;}}

async function openSavedEpisode(id:string,review=false){
  const saved:EpisodeRecord=(await api('episodes/'+id)).episode;if(saved.plan.channelId!==channel?.id)await openChannel(saved.plan.channelId);
  stopTimeline();timeline.take=null;outputTake=null;episode=saved;scope='episode';takeView='versions';selectedTakeId=saved.storyApproval?.takeId||liveTakes().at(-1)?.id||'';editDraft=null;editIndex=0;deleteEpisodeId='';deleteTakeId='';mode=review?'takes':saved.production?'performance':'home';paused=saved.production?.status==='paused';status=review?'Choose a saved version, then approve it for future stories.':'Episode restored. Saved lines and voices are kept.';url();
}

function url(){const target=new URL(location.href);target.search='';if(channel)target.searchParams.set('channel',channel.id);if(episode)target.searchParams.set('episode',episode.id);history.replaceState(null,'',target);}
function stopInput(){speechToken++;recognition?.abort();recognition=null;document.body.dataset.studioListening='false';}
