    const input=pending?.path===path&&pending.input.text===text?pending.input:{...tokens(channel!),text,playback:{playing:player.active||timeline.playing,positionMs:Math.round(stageFrame().timeMs),screenPlaying:screen.playing},...(episode?{episodeId:episode.id,episodeRevision:episode.revision,episodeEpoch:episode.epoch}:{})};
