$('#app').addEventListener('click',event=>{const target=(event.target as HTMLElement).closest<HTMLButtonElement>('[data-action]');if(target&&!target.disabled)void action(target.dataset.action!);});
$('#app').addEventListener('keydown',event=>{const keyboard=event as KeyboardEvent,target=event.target as HTMLElement;if(!target.matches('.workspace-tabs [role="tab"]')||!['ArrowLeft','ArrowRight','Home','End'].includes(keyboard.key))return;const tabs=[...target.parentElement!.querySelectorAll<HTMLButtonElement>('[role="tab"]')],index=tabs.indexOf(target as HTMLButtonElement),next=keyboard.key==='Home'?0:keyboard.key==='End'?tabs.length-1:(index+(keyboard.key==='ArrowRight'?1:tabs.length-1))%tabs.length;keyboard.preventDefault();keyboard.stopPropagation();tabs[next].focus();tabs[next].click();});
$('#app').addEventListener('change',event=>{const target=event.target as HTMLSelectElement;if(target.matches('[data-episode-filter]')){episodeFilter=target.value as typeof episodeFilter;page=0;render();return;}if(target.matches('[data-line-shot]')&&chosenTake()&&editDraft&&SHOTS.includes(target.value)){const line=editionTimeline(chosenTake()!,editDraft)[editIndex];if(line){editDraft.shots=editDraft.shots.filter(shot=>shot.lineId!==line.id);editDraft.shots.push({lineId:line.id,kind:target.value});render();}return;}if(target.matches('[data-saved-version]'))void action('take:'+target.value);});
$('#app').addEventListener('input',event=>{const target=event.target as HTMLInputElement;if(target.id==='episode-search'){episodeSearch=target.value;page=0;render();return;}if(target.id==='screen-headline'&&episode){headlineDrafts[episode.id]=target.value;scene?.showBranding(target.value,true);}if(target.id==='motion-search'){motionSearch=target.value;motionSelection='';page=0;render();}if(target.id==='writer-notes'&&channel)writerNoteDrafts[channel.id]=target.value;if(target.id==='studio-input'){composer=target.value;source='written';retainWords();}if(target.id==='cast-search'){query=target.value;page=0;render();}});
$('#app').addEventListener('toggle',event=>{const node=event.target as HTMLDetailsElement;if(node.matches('.voice-filters')&&document.contains(node))voiceFiltersOpen=node.open;},true);
$('#app').addEventListener('change',event=>{
  const node=event.target as HTMLSelectElement,owner=node.dataset.modelProvider||node.dataset.modelChoice;
  if(node.hasAttribute('data-export-subtitles')){exportSubtitleMode=node.value==='burned-in'?'burned-in':'separate';localStorage.setItem('studio-export-subtitles',exportSubtitleMode);}
  else if(node.hasAttribute('data-adult-comedy')&&channel){const enabled=(node as unknown as HTMLInputElement).checked;void run(async()=>{await reviseChannel({...channel!.definition,adultComedy:enabled});status=enabled?'18+ comedy enabled for future scenes.':'18+ comedy disabled. Future scenes use clean language.';});}
  else if(node.hasAttribute('data-motion-family')){motionFamily=node.value;motionSelection='';page=0;render();}
  else if(node.hasAttribute('data-model-provider')){modelProviders[owner!]=node.value;modelQueries[owner!]='';render();}
  else if(node.hasAttribute('data-model-choice')&&node.value){const brain={provider:node.dataset.provider!,model:node.value};if(owner==='character'&&draft){draft.brain=brain;render();}else if(owner==='writer'&&channel)void run(async()=>{await reviseChannel({...channel!.definition,writingBrain:brain});status='Dialogue writer saved for this room.';});else if(owner==='reviewer'&&channel)void run(async()=>{if(sameReviewModel(writerBrain(),brain))throw new Error('Choose a reviewer different from the writer.');await reviseChannel({...channel!.definition,reviewingBrain:brain});status='Independent script reviewer saved for this room.';});else if(owner==='director'&&channel)void run(async()=>{await reviseChannel({...channel!.definition,orchestrationBrain:brain});status='AI director saved for this room.';});}
  else if(node.hasAttribute('data-voice-engine')){voiceModel=node.value;voiceStyle='all';voiceQuery='';render();}
  else if(node.hasAttribute('data-voice-language')){voiceLanguage=node.value;render();}
  else if(node.hasAttribute('data-voice-style')){voiceStyle=node.value;render();}
  else if(node.hasAttribute('data-voice-choice')&&draft&&node.value){draft.voice={provider:'sarvam',model:voiceModel,id:node.value};render();}
});
$('#app').addEventListener('input',event=>{const node=event.target as HTMLInputElement;if(node.dataset.modelSearch){modelQueries[node.dataset.modelSearch]=node.value;render();}else if(node.id==='voice-search'){voiceQuery=node.value;render();}});
$('#app').addEventListener('submit',event=>{if((event.target as HTMLElement).id==='studio-composer'){event.preventDefault();stopInput();void run(capture);}});
render();
try{scene=new StudioScene(canvas!,command=>void action(command),active=>{activeXR=active;document.body.dataset.studioXr=String(active);render();});}catch{graphicsIssue='The 3D room could not open. Saved room controls are still available.';status=graphicsIssue;error=true;}
scene?.screen(screen.texture,time=>screen.tick(time));scene?.onFrame(()=>{const frame=stageFrame(),production=timeline.take?.productionSnapshot||episode?.production;if(!recorder.offline){music.tick(frame,production?activeTurns(production):[],timeline.take?timeline.captions:player.captions);recorder.frame();}});
document.querySelector<HTMLCanvasElement>('#studio-world')?.addEventListener('webglcontextlost',event=>{event.preventDefault();graphicsIssue='The 3D view paused. Your saved show is safe.';status=graphicsIssue;error=true;watchMode=false;if(recorder.active)recorder.cancel();timeline.pause();music.stop();if(player.active)void player.pause().catch(()=>{});render();});
document.querySelector<HTMLCanvasElement>('#studio-world')?.addEventListener('webglcontextrestored',()=>{graphicsIssue='';error=false;status='The 3D studio is restored. Resume when ready.';render();});
window.addEventListener('resize',()=>render());
window.addEventListener('pagehide',()=>{exportPollingStopped=true;stopInput();player.dispose();void timeline.dispose();screen.dispose();scene?.dispose();});
void run(async()=>{await recoverStoryReceipt();await refresh();const parameters=new URL(location.href).searchParams,id=parameters.get('channel');if(id&&isId(id)){await openChannel(id);const episodeId=parameters.get('episode');if(episodeId&&isId(episodeId)){const saved=(await api('episodes/'+episodeId)).episode;if(saved.plan.channelId!==channel?.id)throw new Error('This episode belongs to another channel.');episode=saved;mode=saved.production?'performance':'home';paused=saved.production?.status==='paused';url();}}if(parameters.has('publishing')){const selected=channels.find(c=>c.id===sessionStorage.getItem('goc-publishing-return-channel'))||channels[0];if(selected&&channel?.id!==selected.id)await openChannel(selected.id);if(channel){mode='settings';settingsPublishing=true;await publishing.load();}status='Returned from publishing authorization. Check the connected account below.';const clean=new URL(location.href);clean.searchParams.delete('publishing');history.replaceState(null,'',clean.pathname+clean.search);} if(pending)status='A previous save needs its receipt. Use Retry save.';}).finally(()=>{document.body.dataset.appReady='true';document.body.dataset.studioReady='true';document.body.dataset.avatarStyle='realistic';window.dispatchEvent(new Event('goc-ready'));});

